using System.Collections.Concurrent;

namespace CleanCode.Examples;

internal static class BoundaryHelpers
{
    internal static byte[] Read(string root, string requestedPath)
    {
        string path = Path.Combine(root, requestedPath);
        if (!path.StartsWith(root, StringComparison.Ordinal))
        {
            throw new ArgumentException("Outside approved directory.");
        }

        return File.ReadAllBytes(path);
    }

    internal static HttpClientHandler CreateHandler() => new()
    {
        ServerCertificateCustomValidationCallback = (_, _, _, _) => true
    };

    internal static ReceiptView GetReceipt(ConcurrentDictionary<string, ReceiptView> receipts, string key, Action recordCreation)
    {
        return receipts.GetOrAdd(key, _ =>
        {
            recordCreation();
            return new ReceiptView(key);
        });
    }
}
